#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ, public SBtnDataEx  {  char szGoto[64];  char szWnd [64];  int nSpecHS;//1- Отображение 2- Управление  bool m_bSet;  bool m_bnoBarChange;  LPARAM lParam;  } Queue_KcaBtn;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PressKcaBtn(DefinePress)  {  Queue_KcaBtn* p = (Queue_KcaBtn*)s;if ( nCode == 0 )    p->m_bPressed = true;  else  if ( nCode == 1 )    { }  else  if ( nCode == 2 )    p->m_bPressed = false;  //  bool bPtInRect = ::PaintSelBtn( q, point, p->mRect, p );  if ( nCode == 2 && bPtInRect )    {		  //		  if ( *p->szWnd != '\0' )			{			OpenMnemoWnd( q.hWnd, p->szWnd );			}		  else		  if ( *p->szGoto != '\0' )			{			static char szGoto[256];			lstrcpy( szGoto, p->szGoto );			::PostMsg( q.hWnd, QUEUE_GOTO, (LPARAM)szGoto );			}			else		  if ( p->lParam != -1 )			{			::PostMsg( q.hWnd, MAKELONG(p->btSendType,nCode), p->lParam );			}  }  //  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintKcaBtn(DefinePaint)  {  QueueP(Queue_KcaBtn);  p->uFormat = DT_CENTER|DT_VCENTER|DT_WORDBREAK;  //  COLORREF color = 0x80ff;  if(!p->m_bnoBarChange)  {	  if ( lstrcmpi( p->szGoto, q.szMnemoBar ) == 0 )	  {		  p->bkgNorma=0x969696;		  p->txtNorma=0xffffff;	  }	  else	  {		  p->bkgNorma=0xE3E3E3;		  p->txtNorma=0;	  }  }  p->txtPress=p->txtNorma;  bool bPressed = PressedButton( p, p->mRect, q );  ::PaintBtn( hDC, p->mRect, p, bPressed );  //  if ( ::GetMnemoStyle() & MNEMO_EDIT )    {    if ( lstrcmpi( "Null", p->szGoto ) == 0 )      {      CMyPen pen(hDC, 0xFF, 2 );      int cx = (p->mRect.left + p->mRect.right)/2;      int cy = (p->mRect.top + p->mRect.bottom)/2;      POINT pt[5] = {{cx,p->mRect.top},{p->mRect.right,cy},{cx,p->mRect.bottom},{p->mRect.left,cy},{cx,p->mRect.top}};      ::Polyline( hDC, pt, 5 );      }    }  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddKcaBtn(DefineTegs)  {  //  AddQueueEx(Queue_KcaBtn);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_BUTTON;  // Определение функции вывода  p->paint = &PaintKcaBtn;  p->press = &PressKcaBtn;  //  DefaultButton( p, teg[0].value );  int nName = 0;  p->nSpecHS= 0;  p->nRegulator = -2;  p->m_bSet=false;  p->m_bnoBarChange=false;  p->lParam = -1;  lstrcpy(p->szFText,"");  //  STegObj obj[] =    {    { 'S', "goto"  , p->szGoto, 63 },    { 'S', "window", p->szWnd , 63 },    { 'S', "ftext", p->szFText , 3 },    { 'I', "name"  , &nName },    { 'I', "specHS", &p->nSpecHS },    { 'B', "setHS" , &p->m_bSet },	{ 'B', "noBarChange" , &p->m_bnoBarChange },    TEG_BUTTON // Кнопочная информация    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  p->nNumber  = def.GetActiveObj();  PostfixButton( p );  if (*p->szFText)  {    p->bDrawF1=true;    p->lfBoldF=p->lf;    p->lfBoldF.lfHeight=-11;    p->lfBoldF.lfWeight=900;  }  //  if ( nName == 0 ) return;  //  struct A { const char* name; UINT lo; };  p->btSendType = QUEUE_SPBTN;  // Специфичные кнопки  static A sp[] =    {    #undef  EnumSPBTN    #define EnumSPBTN( Name, Number, Text ) { Text, Number },    #include "BtnSP.hpp"    };  //  static bool initSP = true;static size_t nSP = sizeof(sp)/sizeof(A);  Qsort( sp, nSP, sizeof(A), initSP );  //  A* m = (A*)SearchName( teg[0].value, sp, nSP, sizeof(A) );  if ( m != NULL )    {    p->lParam = m->lo;    return;    }  ASSERT(0);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~